/* Deutsch Starter V3: plain JavaScript, no backend, no external SDK. */
'use strict';
(() => {
  const CONTENT=window.DEUTSCH_CONTENT, EXAMS=window.DEUTSCH_EXAMS;
  const KEY='deutsch-starter-master-v3';
  const $=(s,root=document)=>root.querySelector(s);
  const $$=(s,root=document)=>Array.from(root.querySelectorAll(s));
  const h=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const enc=v=>encodeURIComponent(String(v??''));
  const localDay=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
  const empty=()=>({version:3,letters:{},lettersWritten:{},completed:{},cards:{},exams:[],practice:[],dayCounts:{},settings:{rate:.8},legacyImported:false});
  const read=()=>{try{const x=JSON.parse(localStorage.getItem(KEY)||'null');if(x&&x.version===3)return Object.assign(empty(),x,{settings:Object.assign({rate:.8},x.settings||{})});}catch{}return empty();};
  let state=read();
  if(!localStorage.getItem(KEY)){
    try{let old=JSON.parse(localStorage.getItem('deutsch-a1-progress-v1')||'null');if(old){state.legacyImported=true;state.letters=old.letters||{};state.lettersWritten=old.writes||{};save(false);}}catch{}
  }
  const ui={view:'home',level:'A0',lesson:null,letter:0,sound:0,practiceMode:'letter-listen',practiceItem:0,practiceAnswer:null,practiceText:'',recognized:'',practiceDone:false,lessonQuiz:null,reviewKeys:[],reviewIndex:0,reviewShow:false,examLevel:'A1',examBoard:'Goethe',examForm:1,examSkill:'all',examMode:'study',exam:null,examResult:null,dialogId:0,dialogStep:0,dialogFeedback:null};
  let toastTimer,recognition=null,recorder=null,recordedURL=null,micStream=null;
  const C=()=>CONTENT.courses;
  const allLessons=()=>Object.values(C()).flat();
  const allPhrases=()=>allLessons().flatMap(l=>l.phrases.map((p,i)=>({key:l.id+':'+i,level:l.level,de:p[0],vi:p[1],lesson:l.title})));
  const phraseLookup=()=>Object.fromEntries(allPhrases().map(p=>[p.key,p]));
  const profile=phraseLookup();
  function save(count=true){try{if(count)state.dayCounts[localDay()]=(state.dayCounts[localDay()]||0)+1;localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('Trình duyệt không lưu được tiến độ. Hãy xuất tệp sao lưu thường xuyên.');return false;}}
  function toast(message){const node=$('#toast');node.textContent=message;node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,4300);}
  const pct=(a,b)=>b?Math.round(a/b*100):0;
  const letterKnown=()=>Object.values(state.letters).filter(Boolean).length;
  const lessonDone=()=>Object.values(state.completed).filter(Boolean).length;
  function todayDue(){return Object.values(state.cards).filter(v=>(v.due||'')<=localDay()).length;}
  function speak(txt,rate=state.settings.rate){if(!('speechSynthesis' in window)){toast('Trình duyệt này không hỗ trợ giọng đọc.');return;}try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(txt);u.lang='de-DE';u.rate=Number(rate)||.8;const voices=speechSynthesis.getVoices();const german=voices.find(x=>/^de[-_]/i.test(x.lang))||voices.find(x=>x.lang==='de');if(german)u.voice=german;u.onerror=()=>toast('Không phát được tiếng Đức. Hãy cài giọng German trên thiết bị hoặc kiểm tra kết nối.');speechSynthesis.speak(u);}catch{toast('Chưa thể phát âm thanh trên thiết bị này.');}}
  function norm(s){return String(s||'').toLocaleLowerCase('de-DE').replace(/[.!?,;:„“"']/g,'').replace(/\s+/g,' ').trim();}
  function tokens(s){return norm(s).split(' ').filter(Boolean);}
  function similarity(a,b){let x=tokens(a),y=tokens(b),n=x.length,m=y.length;if(!n||!m)return 0;let t=Array(m+1).fill(0).map((_,i)=>i);for(let i=1;i<=n;i++){let next=[i];for(let j=1;j<=m;j++)next[j]=Math.min(t[j]+1,next[j-1]+1,t[j-1]+(x[i-1]===y[j-1]?0:1));t=next;}return Math.max(0,Math.round(100*(1-t[m]/Math.max(n,m))));}
  function dayStreak(){let n=0,d=new Date();for(let i=0;i<365;i++){let key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;if(state.dayCounts[key])n++;else if(i>0)break;d.setDate(d.getDate()-1);}return n;}
  function bar(v,total){return `<div class="progressbar" role="progressbar" aria-valuenow="${v}" aria-valuemax="${total||1}"><span style="width:${pct(v,total)}%"></span></div>`;}
  const btn=(label,action,cls='btn',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
  const heading=(title,sub)=>`<div class="section-head"><div><h1>${h(title)}</h1>${sub?`<p class="lead">${sub}</p>`:''}</div></div>`;
  const levelsDesc={A0:'Bảng chữ, ghép âm, bước đầu nghe–viết',A1:'Nói và hiểu các tình huống gần gũi',A2:'Đối thoại công việc và cuộc sống',B1:'Trình bày ý kiến và giao tiếp độc lập'};
  function render(){let html='';try{
    switch(ui.view){
      case 'home':html=renderHome();break;
      case 'alphabet':html=renderAlphabet();break;
      case 'sounds':html=renderSounds();break;
      case 'lessons':html=renderLessons();break;
      case 'lesson':html=renderLesson();break;
      case 'practice':html=renderPractice();break;
      case 'review':html=renderReview();break;
      case 'exams':html=renderExams();break;
      case 'dialogue':html=renderDialogue();break;
      case 'progress':html=renderProgress();break;
      case 'settings':html=renderSettings();break;
      default:html=renderHome();
    }
  }catch(err){console.error(err);html=`<div class="card"><h2>Ứng dụng gặp lỗi hiển thị</h2><p>${h(err.message)}</p>${btn('Về trang chính','home')}</div>`;}
    $('#app').innerHTML=html;$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===ui.view||(ui.view==='lesson'&&n.dataset.view==='lessons')));}
  function go(view,scroll=true){if(ui.view==='exams'&&view!=='exams'&&ui.exam&&!ui.exam.finished)toast('Bài thi đang chạy. Trở lại phòng thi để tiếp tục.');ui.view=view;render();if(scroll)window.scrollTo({top:0,behavior:'instant'});closeMenu();}
  function renderHome(){let done=lessonDone(),total=allLessons().length;
    return `<div class="hero"><div class="eyebrow">LỘ TRÌNH HỌC TIẾNG ĐỨC MIỄN PHÍ</div><h1>Từng chữ cái đến giao tiếp tự tin.</h1><p class="lead">Học nghe, viết, mẫu câu từ A0 → B1. Ôn tập theo tiến độ và luyện thi thử theo Goethe, telc, ÖSD trên iPhone hoặc Windows.</p><div class="actions">${btn('▶ Bắt đầu với bảng chữ cái','open-alphabet')}${btn('Khám phá bài học','open-lessons','btn btn-outline')}</div></div>
    <div class="grid grid-4"><div class="card"><div class="stat-icon">🔤</div><div class="statnum">${letterKnown()}/30</div><div class="statcap">Chữ đã ghi nhớ</div></div><div class="card"><div class="stat-icon">📚</div><div class="statnum">${done}/${total}</div><div class="statcap">Bài đã hoàn thành</div></div><div class="card"><div class="stat-icon">🧠</div><div class="statnum">${todayDue()}</div><div class="statcap">Thẻ đang đến hạn ôn</div></div><div class="card"><div class="stat-icon">🔥</div><div class="statnum">${dayStreak()}</div><div class="statcap">Ngày học liên tục</div></div></div>
    <div class="section-head"><h2>Chọn trình độ</h2><span class="chip">A0 là giai đoạn nhập môn trước A1</span></div><div class="grid grid-4">${['A0','A1','A2','B1'].map(l=>`<div class="card level-card"><span class="tag">${l==='A0'?'Khởi đầu':'CEFR '+l}</span><h2>${l}</h2><div class="sub">${levelsDesc[l]}</div><p class="small muted">${C()[l].length} bài học</p><button class="btn btn-secondary" data-action="pick-level" data-level="${l}">Học ${l} →</button></div>`).join('')}</div>
    <div class="section-head"><h2>Luyện theo mục tiêu</h2></div><div class="grid grid-3"><div class="card"><h3>🎧 Nghe và viết</h3><p class="muted">Nghe âm, chính tả chữ và câu với giọng Đức của thiết bị.</p>${btn('Luyện ngay','open-practice','btn btn-secondary')}</div><div class="card"><h3>📝 Thi thử 3 hội đồng</h3><p class="muted">Chọn A1/A2/B1, kỹ năng, thời gian và xem giải thích.</p>${btn('Chọn đề luyện','open-exams','btn btn-secondary')}</div><div class="card"><h3>💾 Dữ liệu riêng</h3><p class="muted">Lưu tiến độ trên máy, chủ động xuất/nhập bản sao để đổi thiết bị.</p>${btn('Sao lưu','open-progress','btn btn-secondary')}</div></div>
    <p class="notice" style="margin-top:20px">Không có phí tài khoản hay API. Đây là ứng dụng tự học với đề luyện rút gọn do Deutsch Starter biên soạn, <b>không phải đề thi do Goethe, telc hoặc ÖSD cấp phép</b>. Phần nói/viết chưa chấm như giám khảo.</p>`;}
  function renderAlphabet(){const a=CONTENT.alphabet[ui.letter];let first=ui.letter===0,last=ui.letter===CONTENT.alphabet.length-1;
    return `${heading('Bảng chữ cái Đức – 30 ký tự','Học 26 chữ A–Z và Ä, Ö, Ü, ß. Nghe tên chữ, đọc theo, viết rồi ghi nhớ.')}
      <div class="twocol"><div class="card"><div class="toprow"><span class="chip">Chữ ${ui.letter+1}/30</span><span class="chip">${state.letters[a.letter]?'✓ Đã thuộc':'Chưa đánh dấu'}</span></div><div class="letterstage"><div class="bigletter">${h(a.letter)}</div><strong>Tên chữ: ${h(a.name)}</strong><span class="muted">IPA: ${h(a.ipa)}</span><h2 style="margin:0">${h(a.word)}</h2><span class="muted">${h(a.vi)}</span></div><div class="actions">${btn('🔊 Nghe tên chữ','say-letter')}${btn('🔊 Nghe từ mẫu','say-word','btn btn-secondary')}${btn('✓ Đã ghi nhớ','mark-letter','btn btn-outline')}</div><div class="actions">${btn('← Chữ trước','prev-letter','btn btn-outline',first?'disabled':'')}${btn('Chữ tiếp →','next-letter','btn btn-outline',last?'disabled':'')}</div></div>
      <div class="card"><h3>✍️ Viết lại chữ cái</h3><p class="muted">Gõ lại ký tự đang học, dùng đúng dấu khi có Umlaut.</p><div class="field"><label for="letter-write">Nhập chữ</label><input id="letter-write" autocomplete="off" autocapitalize="off" placeholder="Ví dụ: Ä" value=""></div>${btn('Kiểm tra','check-letter')}<div id="letter-feedback" aria-live="polite"></div><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><h3>🔤 Chọn nhanh chữ cái</h3><div class="keygrid">${CONTENT.alphabet.map((x,i)=>`<button class="key ${i===ui.letter?'on':''} ${state.letters[x.letter]?'done':''}" data-action="select-letter" data-index="${i}">${h(x.letter)}</button>`).join('')}</div><p class="hint">ß là chữ thường; dạng viết hoa là ẞ. Hai ký tự này không phải chữ cái mới tách rời trong bảng học cơ bản.</p></div></div>`;}
  function renderSounds(){let x=CONTENT.phonics[ui.sound];return `${heading('Ghép âm & phát âm','Những tổ hợp chữ thường gặp, giúp bạn đọc từ mới chính xác hơn.')}
    <div class="twocol"><div class="card"><div class="toprow"><span class="chip">Quy tắc ${ui.sound+1}/${CONTENT.phonics.length}</span></div><div class="letterstage"><div class="bigletter" style="font-size:84px">${h(x.pattern)}</div><h2>${h(x.ipa)}</h2><p style="max-width:370px">${h(x.note)}</p><strong>Ví dụ: ${h(x.example)}</strong></div><div class="actions">${btn('🔊 Nghe từ ví dụ','say-sound')}${btn('← Trước','prev-sound','btn btn-outline',ui.sound===0?'disabled':'')}${btn('Tiếp →','next-sound','btn btn-outline',ui.sound===CONTENT.phonics.length-1?'disabled':'')}</div></div><div class="card"><h3>Danh sách âm để luyện nhanh</h3><div class="grid grid-2" style="gap:8px">${CONTENT.phonics.map((r,i)=>`<button class="pill ${i===ui.sound?'on':''}" data-action="select-sound" data-index="${i}">${h(r.pattern)}</button>`).join('')}</div><p class="muted small" style="margin-top:18px">Một số âm không có tương đương hoàn toàn trong tiếng Việt. Nghe từ mẫu và tập theo vị trí môi/lưỡi sẽ chính xác hơn việc chỉ đọc phiên âm gần đúng.</p></div></div>`;}
  function renderLessons(){let list=C()[ui.level],done=list.filter(l=>state.completed[l.id]).length;
    return `${heading('Giáo trình A0 → B1','Học từ dễ đến khó. Mỗi bài gồm câu mẫu, nghe phát âm, ôn từ và kiểm tra ngắn.')}
    <div class="toprow"><div class="pillbar">${['A0','A1','A2','B1'].map(l=>`<button class="pill ${ui.level===l?'on':''}" data-action="select-level" data-level="${l}">${l}</button>`).join('')}</div><span class="chip">${done}/${list.length} bài xong</span></div><div class="card" style="margin-bottom:20px"><div class="split-title"><div><h2 style="margin-bottom:6px">Trình độ ${ui.level}</h2><p class="muted" style="margin:0">${levelsDesc[ui.level]}</p></div><strong>${pct(done,list.length)}%</strong></div>${bar(done,list.length)}</div>
    <div class="grid grid-3">${list.map((l,i)=>`<div class="card lesson-card"><div class="split-title"><span class="tag">BÀI ${String(i+1).padStart(2,'0')}</span><span class="chip">${state.completed[l.id]?'✓ Xong':'Chưa học'}</span></div><h3>${h(l.title)}</h3><p class="muted">${h(l.tip)}</p><div class="small muted">${l.phrases.length} mẫu câu · ${l.level}</div><button class="btn ${state.completed[l.id]?'btn-secondary':''}" data-action="open-lesson" data-id="${l.id}">${state.completed[l.id]?'Ôn lại bài':'Vào học'} →</button></div>`).join('')}</div>`;}
  function renderLesson(){const l=allLessons().find(x=>x.id===ui.lesson);if(!l)return renderLessons();
    return `<div class="toprow">${btn('← Trở lại giáo trình','back-lessons','btn btn-outline')}<span class="chip">${l.level} · ${l.phrases.length} mẫu câu</span></div>${heading(l.title,h(l.tip))}<div class="twocol"><div class="card"><div class="toprow"><h2 style="margin:0">Nghe – học – ghi nhớ</h2>${btn('🔊 Nghe cả bài','say-lesson','btn btn-secondary btn-small')}</div>${l.phrases.map((p,i)=>{let key=l.id+':'+i;return `<div class="phrase"><div><div class="de">${h(p[0])}</div><div class="vi">${h(p[1])}</div></div><div class="controls"><button aria-label="Nghe tiếng Đức" data-action="say" data-text="${enc(p[0])}">🔊</button><button class="${state.cards[key]?'saved':''}" title="Thêm vào thẻ ôn tập" aria-label="Lưu thẻ ôn" data-action="toggle-card" data-key="${h(key)}">${state.cards[key]?'★':'☆'}</button></div></div>`;}).join('')}</div><div><div class="card"><h3>💡 Mẹo học</h3><p>${h(l.grammar||l.tip)}</p><p class="muted small">Mỗi câu: nghe → tự đọc → che nghĩa → dịch ngược → ghi nhớ. Bấm ☆ để thêm vào ôn tập cách quãng.</p>${btn('✓ Đánh dấu hoàn thành','complete-lesson','btn btn-secondary')}${state.completed[l.id]?'<p class="answerline">Bạn đã hoàn thành bài này.</p>':''}</div><div class="card" style="margin-top:18px"><h3>🧠 Kiểm tra nhanh</h3><p class="muted small">Chọn nghĩa đúng của câu tiếng Đức.</p><div id="lesson-quiz">${renderLessonQuiz(l)}</div></div></div></div>`;}
  function makeQuiz(l){let idx=Math.floor(Math.random()*l.phrases.length),q=l.phrases[idx];let other=l.phrases.filter((_,i)=>i!==idx).map(p=>p[1]);let pool=[q[1],...other.sort(()=>Math.random()-.5).slice(0,3)].sort(()=>Math.random()-.5);return {de:q[0],vi:q[1],options:pool,answered:false,choice:null};}
  function renderLessonQuiz(l){if(!ui.lessonQuiz)ui.lessonQuiz=makeQuiz(l);const q=ui.lessonQuiz;return `<strong>${h(q.de)}</strong><div style="margin-top:11px">${q.options.map((o,i)=>`<button style="display:block;width:100%;margin:5px 0;text-align:left" class="pill ${q.answered&&q.choice===i?'on':''}" data-action="lesson-quiz-answer" data-index="${i}" ${q.answered?'disabled':''}>${i+1}. ${h(o)}</button>`).join('')}</div>${q.answered?`<p class="answerline ${q.options[q.choice]===q.vi?'':'bad'}">${q.options[q.choice]===q.vi?'Chính xác!':'Cần ôn thêm.'} Đáp án: ${h(q.vi)}</p>`:''}${btn('Câu khác →','lesson-quiz-next','btn btn-outline btn-small')}`;}
  function newPractice(){const letters=CONTENT.alphabet;ui.practiceDone=false;ui.practiceAnswer=null;ui.practiceText='';ui.recognized='';
    if(ui.practiceMode.startsWith('letter')){ui.practiceItem=Math.floor(Math.random()*letters.length);let correct=letters[ui.practiceItem].letter;let choices=[correct];while(choices.length<4){let c=letters[Math.floor(Math.random()*letters.length)].letter;if(!choices.includes(c))choices.push(c);}ui.practiceChoices=choices.sort(()=>Math.random()-.5);}
    else{let pool=allPhrases().filter(p=>p.level===ui.level);if(pool.length===0)pool=allPhrases();ui.practiceTarget=pool[Math.floor(Math.random()*pool.length)];}
  }
  function renderPractice(){if(!ui.practiceChoices&&!ui.practiceTarget)newPractice();let mode=ui.practiceMode;const letter=CONTENT.alphabet[ui.practiceItem],target=ui.practiceTarget;
    let center='';if(mode==='letter-listen'){
      center=`<div class="quizbox"><span class="chip">Bài nghe chữ cái</span><h2>Bạn nghe được chữ nào?</h2><p class="muted">Bấm phát âm rồi chọn đáp án.</p>${btn('🔊 Phát tên chữ','play-practice') }<div class="grid grid-2" style="margin-top:15px">${ui.practiceChoices.map(x=>`<button class="pill" data-action="practice-choice" data-value="${h(x)}" ${ui.practiceDone?'disabled':''}>${h(x)}</button>`).join('')}</div>${ui.practiceDone?`<p class="answerline ${ui.practiceAnswer===letter.letter?'':'bad'}">${ui.practiceAnswer===letter.letter?'Chính xác!':'Chưa đúng.'} Đáp án: ${h(letter.letter)} (${h(letter.name)})</p>`:''}</div>`;
    }else if(mode==='letter-write'){
      center=`<div class="quizbox"><span class="chip">Chính tả chữ cái</span><h2>Nghe và nhập chữ</h2>${btn('🔊 Phát tên chữ','play-practice')}<div class="field"><label for="practice-text">Chữ bạn nghe thấy</label><input id="practice-text" autocomplete="off" autocapitalize="off" value="${h(ui.practiceText)}" placeholder="Nhập A, Ä, ß..."></div>${btn('Kiểm tra','check-practice','btn',ui.practiceDone?'disabled':'')}${ui.practiceDone?`<p class="answerline ${norm(ui.practiceText)===norm(letter.letter)?'':'bad'}">Đáp án: ${h(letter.letter)}</p>`:''}</div>`;
    }else if(mode==='dictation'){
      center=`<div class="quizbox"><span class="chip">Nghe và chép chính tả · ${h(target.level)}</span><h2>Nghe câu rồi viết lại</h2><p class="muted">Dấu ä/ö/ü/ß rất quan trọng; dấu câu và chữ hoa không tính lỗi trong bài tập này.</p>${btn('🔊 Nghe câu','play-practice')}${btn('🔊 Nghe chậm','play-practice-slow','btn btn-outline')}<div class="field"><label for="practice-text">Câu tiếng Đức</label><textarea id="practice-text" rows="3" autocomplete="off" placeholder="Gõ những gì bạn nghe thấy...">${h(ui.practiceText)}</textarea></div>${btn('Kiểm tra chính tả','check-practice','btn',ui.practiceDone?'disabled':'')}${ui.practiceDone?`<p class="answerline ${norm(ui.practiceText)===norm(target.de)?'':'bad'}">${norm(ui.practiceText)===norm(target.de)?'Đúng rồi!':'Hãy so sánh với câu mẫu.'}<br>Câu đúng: ${h(target.de)}<br>Nghĩa: ${h(target.vi)}</p>`:''}</div>`;
    }else{
      const available=Boolean(window.SpeechRecognition||window.webkitSpeechRecognition);
      center=`<div class="quizbox"><span class="chip">Luyện nói · nhận diện lời nói (nếu được hỗ trợ)</span><h2>${h(target.de)}</h2><p class="muted">${h(target.vi)}</p><div class="actions">${btn('🔊 Nghe câu chuẩn','play-practice')}${btn('🎙️ Bắt đầu nói','start-recognition','btn btn-secondary',available?'':'disabled')}</div>${!available?'<p class="notice">Trình duyệt này không cung cấp tính năng nhận diện giọng nói phù hợp. Bạn vẫn có thể nghe và tự đọc theo. iPhone Safari có thể bị giới hạn.</p>':''}${ui.recognized?`<div class="result-card"><b>Máy nhận diện:</b><p>${h(ui.recognized)}</p><p class="muted">Mức khớp bản chép lời: <b>${similarity(ui.recognized,target.de)}%</b>. Đây KHÔNG phải điểm phát âm.</p></div>`:''}<p class="hint">Nhận diện giọng nói của trình duyệt có thể sử dụng dịch vụ bên ngoài, cần Internet, và không hoạt động trên mọi iPhone. Không có kết nối trực tiếp từ ứng dụng này tới API trả phí.</p></div>`;
    }
    return `${heading('Luyện nghe – nói – viết','Thực hành nhanh theo mức độ của bạn, không cần tài khoản.')}
      <div class="toprow"><div class="pillbar">${[['letter-listen','Nghe chữ'],['letter-write','Viết chữ'],['dictation','Chép chính tả'],['speak','Luyện nói']].map(([m,t])=>`<button class="pill ${mode===m?'on':''}" data-action="practice-mode" data-mode="${m}">${t}</button>`).join('')}</div></div>
      <div class="twocol"><div class="card"><div class="toprow"><h2 style="margin:0">Bài luyện</h2>${btn('Đổi câu ↻','practice-next','btn btn-outline btn-small')}</div>${center}</div><div class="card"><h3>Chọn trình độ câu nghe</h3><div class="pillbar">${['A0','A1','A2','B1'].map(l=>`<button class="pill ${ui.level===l?'on':''}" data-action="practice-level" data-level="${l}">${l}</button>`).join('')}</div><div class="info" style="margin-top:18px">✓ Chữ cái và câu mẫu đã tải dùng được ngoại tuyến.<br>✓ Giọng đọc dùng trình duyệt/hệ điều hành và có thể phụ thuộc mạng.<br>✓ Không đưa ra điểm phát âm giả. Người học có thể nghe–so sánh và tự cải thiện.</div><h3 style="margin-top:25px">Gợi ý luyện mỗi ngày</h3><ol class="rubric"><li>Nghe 3 lần, không nhìn chữ.</li><li>Nhại lại chậm và rõ.</li><li>Viết ra những gì nghe được.</li><li>So sánh và ôn phần bị sai.</li></ol></div></div>`;}
  function reviewKeys(){return Object.keys(state.cards).filter(x=>profile[x]).sort((a,b)=>(state.cards[a].due||'').localeCompare(state.cards[b].due||''));}
  function renderReview(){const keys=reviewKeys();if(!keys.length)return `${heading('Ôn tập thông minh','Thêm các câu vào bộ thẻ học rồi ôn theo lịch nhắc.') }<div class="empty"><h2>Chưa có thẻ học</h2><p>Vào giáo trình và bấm ☆ ở câu muốn ghi nhớ.</p>${btn('Mở giáo trình','open-lessons')}</div>`;
    if(ui.reviewIndex>=keys.length)ui.reviewIndex=0;let key=keys[ui.reviewIndex],p=profile[key],card=state.cards[key],due=keys.filter(k=>(state.cards[k].due||'')<=localDay()).length;
    return `${heading('Ôn tập thông minh','Đánh dấu Dễ / Khó / Chưa thuộc để thay đổi thời điểm ôn tiếp theo.')}
      <div class="toprow"><span class="chip">Thẻ ${ui.reviewIndex+1}/${keys.length}</span><span class="chip">${due} thẻ đến hạn · ${h(card.due||'hôm nay')}</span></div><div class="twocol"><div class="card"><button class="flashcard" data-action="review-flip" aria-label="Lật thẻ" style="width:100%;border:1px solid #dbe5fc"><span class="caption">${h(p.level)} · Bấm để ${ui.reviewShow?'ẩn':'xem'} nghĩa</span><span class="front">${h(p.de)}</span>${ui.reviewShow?`<span class="back">${h(p.vi)}</span>`:'<span class="caption">Đoán nghĩa tiếng Việt trước</span>'}</button><div class="actions">${btn('🔊 Nghe câu','say','btn btn-secondary',`data-text="${enc(p.de)}"`)}${btn('← Trước','review-prev','btn btn-outline')}${btn('Tiếp →','review-next','btn btn-outline')}</div><div class="actions">${btn('Chưa thuộc','review-again','btn btn-danger')}${btn('Hơi khó','review-hard','btn btn-secondary')}${btn('Đã thuộc','review-easy')}</div></div><div class="card"><h3>Cách ôn cách quãng</h3><p>Thẻ khó quay lại sớm. Thẻ dễ sẽ xuất hiện thưa hơn.</p><div class="listrow"><span>Chưa thuộc</span><b>Ôn lại ngày mai</b></div><div class="listrow"><span>Hơi khó</span><b>Ôn sau 2 ngày</b></div><div class="listrow"><span>Đã thuộc</span><b>Ôn sau 3 → 7 → 14 → 30 ngày</b></div><div class="notice" style="margin-top:17px">Lịch này là quy tắc ôn đơn giản, không phải AI cá nhân hóa bằng máy học.</div></div></div>`;}
  const DIALOGUES=[
    {title:'01 · Gọi món tại quán cà phê',level:'A1',steps:[['Guten Tag! Was möchten Sie trinken?',['Ich hätte gern einen Kaffee, bitte.','Ich bin zwanzig Jahre alt.','Morgen ist Montag.'],0],['Mit oder ohne Milch?',['Ich lerne Deutsch.','Ohne Milch, bitte.','Ich wohne in Berlin.'],1],['Möchten Sie sonst noch etwas?',['Wie alt bist du?','Es ist sonnig.','Ein Stück Kuchen, bitte.'],2]]},
    {title:'02 · Hỏi đường đến nhà ga',level:'A1',steps:[['Entschuldigung, kann ich Ihnen helfen?',['Ja, wo ist der Bahnhof?','Ich esse gern Reis.','Ich habe einen Bruder.'],0],['Gehen Sie geradeaus und dann rechts.',['Ich bin krank.','Vielen Dank für Ihre Hilfe!','Ich arbeite als Lehrer.'],1],['Der Bahnhof ist ganz in der Nähe.',['Ich habe keinen Hunger.','Es regnet.','Super, danke schön!'],2]]},
    {title:'03 · Đổi lịch khám bác sĩ',level:'A2',steps:[['Praxis Müller, guten Tag. Wie kann ich Ihnen helfen?',['Ich möchte meinen Termin verschieben.','Ich habe einen neuen Fernseher.','Ich gehe ins Kino.'],0],['Wann haben Sie Zeit?',['Ich bin sehr müde.','Am Donnerstagvormittag hätte ich Zeit.','Ich spreche drei Sprachen.'],1],['Donnerstag um 10 Uhr ist frei. Passt Ihnen das?',['Ich wohne hier.','Das Fahrrad ist blau.','Ja, das passt. Vielen Dank!'],2]]},
    {title:'04 · Cùng tổ chức bữa tiệc',level:'B1',steps:[['Wir möchten eine Feier organisieren. Wann passt es dir?',['Am Samstag hätte ich Zeit.','Die Jacke ist klein.','Das Wetter gestern.'],0],['Wer übernimmt die Einladungen?',['Wir fahren mit dem Zug.','Ich kann die Einladungen schreiben.','Ich habe keine Geschwister.'],1],['Und was machen wir mit dem Essen?',['Ich habe Hunger.','Ich bin 28 Jahre alt.','Wir könnten gemeinsam etwas kochen.'],2]]},
    {title:'05 · Thảo luận việc học online',level:'B1',steps:[['Was hältst du von Online-Unterricht?',['Ich finde ihn flexibel und praktisch.','Ich wohne in einem Haus.','Es kostet fünf Euro.'],0],['Gibt es auch Nachteile?',['Ich trinke Kaffee.','Ja, manchmal fehlt der direkte Kontakt.','Der Bus fährt um acht.'],1],['Was würdest du empfehlen?',['Ich brauche einen Termin.','Es ist sonnig.','Eine Kombination aus Online- und Präsenzunterricht.'],2]]},
  ];
  function renderDialogue(){let d=DIALOGUES[ui.dialogId],step=d.steps[ui.dialogStep];return `${heading('Hội thoại tình huống','Luyện phản xạ qua các kịch bản tương tác ngoại tuyến; đây là hội thoại theo nhánh, không phải AI sáng tạo tự do.')}
    <div class="twocol"><div class="card"><div class="field"><label for="dialog-select">Chọn tình huống</label><select id="dialog-select" data-action-change="dialog-select">${DIALOGUES.map((v,i)=>`<option value="${i}" ${i===ui.dialogId?'selected':''}>${h(v.title)} · ${v.level}</option>`).join('')}</select></div><span class="chip">Bước ${ui.dialogStep+1}/${d.steps.length}</span><div class="quizbox" style="margin-top:15px"><p class="muted small">👤 Người Đức nói</p><h2>${h(step[0])}</h2>${btn('🔊 Nghe câu hỏi','dialog-say','btn btn-secondary')}</div><h3>Chọn câu trả lời hợp lý:</h3>${step[1].map((text,i)=>`<button class="pill" style="width:100%;margin:5px 0;text-align:left" data-action="dialog-answer" data-index="${i}">${h(text)}</button>`).join('')}${ui.dialogFeedback!==null?`<p class="answerline ${ui.dialogFeedback===step[2]?'':'bad'}">${ui.dialogFeedback===step[2]?'Đúng! Chọn tiếp tục để sang câu sau.':'Câu này chưa phù hợp ngữ cảnh, hãy thử lại.'}</p>`:''}<div class="actions">${btn('Tiếp tục →','dialog-next','btn',ui.dialogFeedback!==step[2]?'disabled':'')}${btn('Làm lại','dialog-reset','btn btn-outline')}</div></div><div class="card"><h3>Học giao tiếp hiệu quả</h3><ol class="rubric"><li>Nghe người đối thoại nói trước.</li><li>Tự trả lời thành tiếng.</li><li>Đọc ba phương án và chọn câu phù hợp.</li><li>Nghe câu trả lời đúng và lặp lại.</li></ol><div class="notice">Phần này hoạt động ngoại tuyến, không gọi Gemini/ChatGPT, không phát sinh chi phí API. Để hội thoại AI tự do thực sự cần thêm mô hình hoặc dịch vụ riêng.</div></div></div>`;}
  function renderProgress(){let done=lessonDone(),history=state.exams.slice().reverse().slice(0,12),days=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-(6-i));let k=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return {key:k,num:state.dayCounts[k]||0};});const max=Math.max(1,...days.map(x=>x.num));
    return `${heading('Tiến độ & sao lưu','Dữ liệu chỉ nằm trên thiết bị/trình duyệt hiện tại; bạn chủ động chuyển bản sao giữa iPhone và Windows.')}
    <div class="grid grid-4"><div class="card"><div class="statnum">${letterKnown()}/30</div><div class="statcap">Chữ cái đã thuộc</div>${bar(letterKnown(),30)}</div><div class="card"><div class="statnum">${done}/${allLessons().length}</div><div class="statcap">Bài học đã hoàn thành</div>${bar(done,allLessons().length)}</div><div class="card"><div class="statnum">${Object.keys(state.cards).length}</div><div class="statcap">Thẻ ôn tập</div></div><div class="card"><div class="statnum">${state.exams.length}</div><div class="statcap">Lần thi thử</div></div></div>
    <div class="grid grid-2" style="margin-top:19px"><div class="card"><h3>Hoạt động 7 ngày gần đây</h3><div class="chart-bars" style="margin-bottom:30px">${days.map(x=>`<div title="${h(x.key)}: ${x.num} hoạt động" style="height:${Math.max(5,x.num/max*100)}%"><span>${h(x.key.slice(5))}</span></div>`).join('')}</div><p class="muted small">Chỉ đếm thao tác học đã lưu, không tính số phút sử dụng thực tế.</p></div><div class="card"><h3>Sao lưu dữ liệu</h3><p>Xuất tệp JSON định kỳ. Trên iPhone lưu vào ứng dụng Tệp (Files), rồi nhập trên Windows hoặc ngược lại.</p><div class="actions">${btn('⬇ Xuất tiến độ .json','export')}${btn('⬆ Nhập tiến độ .json','choose-import','btn btn-secondary')}</div><input type="file" id="import-file" accept="application/json,.json" hidden><p class="hint">Khi nhập, phần mềm hỏi xác nhận trước khi thay thế dữ liệu hiện tại. Không cần tài khoản hay máy chủ.</p></div></div>
    <div class="card" style="margin-top:20px"><h3>Lịch sử thi thử gần nhất</h3>${history.length?`<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse"><thead><tr><th style="text-align:left;padding:10px">Ngày</th><th style="text-align:left;padding:10px">Đề</th><th style="text-align:left;padding:10px">Điểm nghe/đọc</th></tr></thead><tbody>${history.map(x=>`<tr><td style="padding:10px;border-top:1px solid #e8edf6">${h(x.at.slice(0,10))}</td><td style="padding:10px;border-top:1px solid #e8edf6">${h(x.board)} ${h(x.level)} – ${h(x.skill)}</td><td style="padding:10px;border-top:1px solid #e8edf6">${x.correct}/${x.total}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Chưa có bài thi thử nào được nộp.</p>'}</div><div class="notice" style="margin-top:17px">Nếu xóa dữ liệu trang web, xóa cấu hình Edge hoặc gỡ PWA kèm dữ liệu, tiến độ có thể mất. Thường xuyên xuất tệp sao lưu để tránh rủi ro.</div>`;}
  function renderSettings(){const mic=Boolean(window.SpeechRecognition||window.webkitSpeechRecognition),secure=window.isSecureContext;
    return `${heading('Cài đặt & hướng dẫn','Ứng dụng web tĩnh không phí API, không cần tài khoản. Phù hợp iPhone và Windows.')}
      <div class="grid grid-2"><div class="card"><h3>🔊 Cấu hình giọng đọc</h3><div class="field"><label for="tts-rate">Tốc độ phát âm</label><select id="tts-rate" data-action-change="tts-rate"><option value="0.65" ${state.settings.rate===.65?'selected':''}>Chậm 0.65×</option><option value="0.8" ${state.settings.rate===.8?'selected':''}>Vừa 0.8×</option><option value="1" ${state.settings.rate===1?'selected':''}>Bình thường 1.0×</option></select></div>${btn('🔊 Kiểm tra giọng Đức','say-test')}<p class="hint">Giọng đọc tiếng Đức dùng giọng của hệ điều hành hoặc trình duyệt và có thể cần Internet.</p></div>
      <div class="card"><h3>📱 Tình trạng thiết bị</h3><div class="listrow"><span>Giao thức an toàn / localhost</span><strong>${secure?'Có':'Chưa'}</strong></div><div class="listrow"><span>Đọc văn bản TTS</span><strong>${'speechSynthesis' in window?'Có':'Không'}</strong></div><div class="listrow"><span>Nhận dạng giọng nói</span><strong>${mic?'Có API':'Không có API'}</strong></div><div class="listrow"><span>Service worker</span><strong>${'serviceWorker' in navigator?'Có API':'Không có API'}</strong></div><p class="hint">“Có API” không bảo đảm nhận dạng chính xác hoặc hoạt động ngoại tuyến.</p></div>
      <div class="card"><h3>📲 Cài lên iPhone</h3><ol class="rubric"><li>Đưa thư mục APP lên GitHub Pages (HTTPS).</li><li>Mở đường dẫn bằng Safari.</li><li>Chia sẻ → Thêm vào Màn hình chính → Thêm.</li><li>Mở một lần khi có mạng để tải dữ liệu học ngoại tuyến.</li></ol><p class="hint">Muốn PWA chạy qua tên miền HTTPS, không dùng đường dẫn file://.</p></div>
      <div class="card"><h3>🖥️ Chạy Windows trên ổ I</h3><ol class="rubric"><li>Giải nén gói ứng dụng vào I:\\TOOL HOC TIENG DUC.</li><li>Chạy START_WINDOWS.bat.</li><li>Edge mở cửa sổ riêng với hồ sơ và cache trên ổ I.</li><li>Tiến độ lưu trong hồ sơ này; định kỳ xuất JSON.</li></ol><p class="hint">Ứng dụng và hồ sơ Edge đặt trên I; Windows/Edge vẫn có thể sử dụng thành phần hệ thống trên ổ C.</p></div></div>
      <div class="card" style="margin-top:18px"><h3>Quản lý dữ liệu</h3><p class="muted">Chỉ xóa dữ liệu khi đã sao lưu và chắc chắn muốn làm lại từ đầu.</p>${btn('⬇ Sao lưu trước','export','btn btn-secondary')} ${btn('Xóa toàn bộ tiến độ','reset','btn btn-danger')}</div>`;}
  function examConfig(){return EXAMS.boards[ui.examBoard][ui.examLevel];}
  const sectionLabels={listening:'Hören · Nghe',reading:'Lesen · Đọc',writing:'Schreiben · Viết',speaking:'Sprechen · Nói'};
  const boards=['Goethe','telc','ÖSD'];
  function renderExams(){if(ui.examResult)return renderExamResults();if(ui.exam)return renderExamSession();let c=examConfig();let columns=Object.entries(c.times).map(([key,min])=>`<div class="listrow"><span>${sectionLabels[key]}</span><b>${min} phút${ui.examBoard==='ÖSD'&&ui.examLevel==='A2'&&key==='speaking'?' (tham khảo)':''}</b></div>`).join('');
    return `${heading('Phòng thi thử A1 · A2 · B1','Chọn kỳ thi, cấp độ, kỹ năng và bộ đề. Có đồng hồ, đáp án, giải thích và lưu kết quả.')}
    <div class="notice"><b>Cần biết:</b> Đây là <b>đề luyện tự biên soạn, rút gọn</b> (không đủ số câu, định dạng, audio dựng sẵn hay chấm điểm như kỳ thi thực). Thời lượng ở bảng bên phải tham chiếu thông tin chính thức; chế độ có đồng hồ trong ứng dụng được rút ngắn để phù hợp bài tập.</div>
    <div class="twocol" style="margin-top:18px"><div class="card"><h2>Thiết lập bài thi</h2>
      <div class="field"><label for="exam-level">Cấp độ</label><select id="exam-level" data-action-change="exam-level">${['A1','A2','B1'].map(l=>`<option ${ui.examLevel===l?'selected':''} value="${l}">${l}</option>`).join('')}</select></div>
      <div class="field"><label for="exam-board">Hội đồng</label><select id="exam-board" data-action-change="exam-board">${boards.map(l=>`<option ${ui.examBoard===l?'selected':''} value="${l}">${h(l)}</option>`).join('')}</select></div>
      <div class="field"><label for="exam-form">Bộ câu hỏi</label><select id="exam-form" data-action-change="exam-form">${[1,2,3].map(l=>`<option ${ui.examForm===l?'selected':''} value="${l}">Bộ ${l} · đề luyện nguyên bản</option>`).join('')}</select></div>
      <div class="field"><label for="exam-skill">Phần muốn thi</label><select id="exam-skill" data-action-change="exam-skill"><option value="all" ${ui.examSkill==='all'?'selected':''}>Tổng hợp 4 kỹ năng</option>${Object.entries(sectionLabels).map(([k,v])=>`<option value="${k}" ${ui.examSkill===k?'selected':''}>${h(v)}</option>`).join('')}</select></div>
      <div class="field"><label for="exam-mode">Chế độ</label><select id="exam-mode" data-action-change="exam-mode"><option value="study" ${ui.examMode==='study'?'selected':''}>Luyện không giới hạn thời gian</option><option value="timed" ${ui.examMode==='timed'?'selected':''}>Thi rút gọn có đồng hồ</option></select></div>
      ${btn('▶ Bắt đầu làm đề','exam-start','btn btn-wide')}<p class="hint">Mỗi bộ có khoảng 9 câu nghe + 9 câu đọc (telc bổ sung Sprachbausteine) và phần viết/nói theo nhiệm vụ. Câu giữa các bộ có thể trùng một phần.</p></div>
      <div class="card"><span class="tag">${h(ui.examBoard)} · ${h(ui.examLevel)}</span><h2 style="margin-top:12px">${h(c.label)}</h2><p>${h(c.format)}</p><h3>Thời lượng kỳ thi chính thức – tham khảo</h3>${columns}<p class="hint">Nếu hội đồng gộp đọc–viết, phần mềm phân chia thời gian luyện theo từng kỹ năng để bạn dễ chọn.</p><div class="actions"><a class="btn btn-outline" target="_blank" rel="noopener noreferrer" href="${h(c.official)}">Xem thông tin chính thức ↗</a><a class="btn btn-secondary" target="_blank" rel="noopener noreferrer" href="${h(c.practice)}">Tài liệu mẫu chính thức ↗</a></div></div></div>`;}
  function makeExam(){let level=ui.examLevel,board=ui.examBoard,form=Number(ui.examForm),bi=boards.indexOf(board),start=(bi*4+(form-1)*7)%18;
    const pick=(xs,n,offset=0)=>Array.from({length:n},(_,i)=>({ ...xs[(start+offset+i*5)%xs.length],id:offset+'-'+i}));
    let reading=pick(EXAMS.banks[level].reading,9),listening=pick(EXAMS.banks[level].listening,9,2);
    if(board==='telc')reading=reading.concat(EXAMS.languageElements[level].map((q,i)=>({...q,id:'sprach-'+i,language:true})));
    let writ=Array.from({length:2},(_,i)=>EXAMS.writing[level][(bi+form+i)%EXAMS.writing[level].length]);
    let speak=Array.from({length:2},(_,i)=>EXAMS.speaking[level][(bi+form+i)%EXAMS.speaking[level].length]);
    return {level,board,form,mode:ui.examMode,scope:ui.examSkill,section:ui.examSkill==='all'?'listening':ui.examSkill,reading,listening,writing:writ,speaking:speak,answers:{},text:{},at:Date.now(),deadline:ui.examMode==='timed'?Date.now()+(ui.examSkill==='all'?30:12)*60000:0,finished:false};
  }
  function examSection(sess){const section=sess.section,qs=sess[section];
    if(section==='reading'||section==='listening')return qs.map((q,i)=>{let id=section+'-'+i,sel=sess.answers[id];return `<article class="examq"><div class="toprow"><span class="chip">Câu ${i+1}/${qs.length}</span>${q.language?'<span class="tag">Sprachbausteine</span>':''}</div>${section==='reading'?`<div class="source">${h(q.text)}</div>`:`<div class="actions" style="margin:8px 0 13px">${btn('🔊 Nghe đoạn '+(i+1),'exam-say','btn btn-secondary btn-small',`data-index="${i}"`)}</div>`}<h3>${h(q.question)}</h3>${q.options.map((a,k)=>`<label class="choice"><input type="radio" name="${h(id)}" data-exam-answer="${h(id)}" value="${k}" ${sel===k?'checked':''}><span>${h(a)}</span></label>`).join('')}</article>`;}).join('');
    if(section==='writing')return qs.map((q,i)=>`<article class="examq"><span class="chip">Bài ${i+1}/${qs.length}</span><h3 style="margin-top:12px">${h(q.title)}</h3><p class="source">${h(q.prompt)}</p><div class="field"><label for="essay-${i}">Bài viết tiếng Đức (lưu trong phiên thi đến khi nộp)</label><textarea data-essay="writing-${i}" id="essay-${i}" rows="7" placeholder="Viết bằng tiếng Đức…">${h(sess.text['writing-'+i]||'')}</textarea></div><span class="hint">${tokens(sess.text['writing-'+i]||'').length} từ · Chưa có chấm điểm ngữ pháp tự động</span></article>`).join('');
    return qs.map((q,i)=>`<article class="examq"><span class="chip">Bài nói ${i+1}/${qs.length}</span><h3 style="margin-top:12px">${h(q.title)}</h3><p class="source">${h(q.prompt)}</p>${btn('🔊 Nghe câu mẫu sau khi tự thử','exam-sample-say','btn btn-outline btn-small',`data-index="${i}"`)}<div class="field"><label for="speaking-notes-${i}">Ghi chú bài nói (tùy chọn)</label><textarea data-essay="speaking-${i}" id="speaking-notes-${i}" rows="4" placeholder="Ghi ý chính; hãy tự nói thành tiếng...">${h(sess.text['speaking-'+i]||'')}</textarea></div></article>`).join('')+`<div class="info" style="margin-top:10px">🎙️ Bạn có thể luyện đọc to và tự ghi âm bằng nút bên dưới (nếu trình duyệt cho phép micro). Âm thanh chỉ được giữ tạm trên thiết bị, không tải lên máy chủ.</div><div class="actions">${btn('🎙️ Bắt đầu / Dừng ghi âm','exam-record','btn btn-secondary',('MediaRecorder'in window&&navigator.mediaDevices)?'':'disabled')}</div><div id="audio-recording" style="margin-top:12px"></div>`;
  }
  function examTime(sess){if(!sess.deadline)return 'Không giới hạn';const left=Math.max(0,Math.ceil((sess.deadline-Date.now())/1000));return `${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;}
  function renderExamSession(){const s=ui.exam,active=s.scope==='all'?['listening','reading','writing','speaking']:[s.scope];
    return `<div class="toprow"><div><div class="eyebrow">ĐỀ LUYỆN RÚT GỌN · KHÔNG PHẢI ĐỀ CHÍNH THỨC</div><h1>${h(s.board)} ${h(s.level)} · Bộ ${s.form}</h1></div><div class="chip">⏱ <span id="exam-clock" class="exam-clock">${examTime(s)}</span></div></div><div class="notice">Bản nghe được tạo bởi TTS của thiết bị, không phải audio bài thi chính thức. Điểm tự động chỉ áp dụng nghe/đọc/ngôn ngữ; viết/nói cần người đánh giá.</div>
      <div class="examnav">${active.map(section=>`<button class="${s.section===section?'on':''}" data-action="exam-section" data-section="${section}">${sectionLabels[section]}</button>`).join('')}</div><div class="card"><div class="split-title"><h2>${sectionLabels[s.section]}</h2><span class="chip">${s[s.section].length} câu/bài</span></div>${examSection(s)}<div class="actions">${btn('✓ Nộp bài & xem đáp án','exam-submit')}${btn('Hủy bài thi','exam-cancel','btn btn-outline')}</div></div><p class="hint" style="margin-top:14px">Thời gian của bài rút gọn ${s.deadline?'30 phút tổng hợp hoặc 12 phút cho một kỹ năng':'không giới hạn'}. Không thể dùng điểm này để kết luận đỗ/trượt chứng chỉ.</p>`;}
  function finishExam(expired=false){let s=ui.exam;if(!s||s.finished)return;stopMic();s.finished=true;let tests=[];for(const part of ['listening','reading']){if(s.scope!=='all'&&s.scope!==part)continue;s[part].forEach((q,i)=>{let val=s.answers[part+'-'+i];tests.push({part,i,q,choice:val,correct:val===q.correct});});}
    let correct=tests.filter(x=>x.correct).length,total=tests.length;
    state.exams.push({at:new Date().toISOString(),board:s.board,level:s.level,skill:s.scope,form:s.form,correct,total,expired});if(state.exams.length>150)state.exams=state.exams.slice(-150);save();ui.examResult={session:s,tests,correct,total,expired};ui.exam=null; if(ui.view==='exams')render();}
  function renderExamResults(){let r=ui.examResult,s=r.session;let subjective=['writing','speaking'].filter(x=>s.scope==='all'||s.scope===x);
    return `${heading('Kết quả đề luyện','Đáp án, giải thích và mẫu tham khảo để bạn học từ câu sai.')}
    <div class="card"><div class="eyebrow">${h(s.board)} ${h(s.level)} · Bộ ${s.form}</div><div class="summary-score">${r.total?`${r.correct}/${r.total}`:'Chưa chấm điểm'}</div><h2>${r.total?`${pct(r.correct,r.total)}% câu nghe/đọc đúng`:'Bài tự luận'}</h2><p class="muted">${r.expired?'Đồng hồ đã hết giờ. ':''}Kết quả chỉ tính trắc nghiệm. Không phải đánh giá chính thức hay dự đoán đỗ/trượt.</p>${btn('← Chọn bài luyện khác','exam-back')}${btn('⬇ Sao lưu tiến độ','export','btn btn-outline')}</div>
    ${r.tests.length?`<div class="card" style="margin-top:18px"><h2>Đáp án và giải thích</h2>${r.tests.map((e,i)=>`<div class="examq"><span class="tag">${e.part==='listening'?'Hören':'Lesen'} · Câu ${e.i+1}</span><p class="source">${h(e.q.text)}</p><strong>${h(e.q.question)}</strong><p class="answerline ${e.correct?'':'bad'}">${e.correct?'✓ Đúng':'✕ Chưa đúng'} · Bạn chọn: ${e.choice===undefined?'(bỏ trống)':h(e.q.options[e.choice])}<br>Đáp án: ${h(e.q.options[e.q.correct])}</p><p class="muted small">${h(e.q.explain)}</p></div>`).join('')}</div>`:''}
    ${subjective.map(part=>`<div class="card" style="margin-top:18px"><h2>${sectionLabels[part]} – Tự đối chiếu</h2><div class="notice">Bài mẫu chỉ là một cách trả lời phù hợp. Không có điểm chấm ngữ pháp, độ trôi chảy hay phát âm tự động.</div>${s[part].map((p,i)=>`<div class="examq"><h3>${h(p.title)}</h3><p>${h(p.prompt)}</p><b>Phần bạn đã viết / ghi chú:</b><p class="pre">${h(s.text[part+'-'+i]||'(Bạn chưa nhập nội dung)')}</p><b>Tiêu chí cần có:</b><ul class="rubric">${p.check.map(v=>`<li>${h(v)}</li>`).join('')}</ul><b>Bài mẫu tham khảo:</b><p class="subjective">${h(p.sample)}</p>${btn('🔊 Nghe mẫu','say','btn btn-secondary btn-small',`data-text="${enc(p.sample)}"`)}</div>`).join('')}</div>`).join('')}`;}
  function stopMic(){if(recorder&&recorder.state==='recording')recorder.stop();if(micStream){micStream.getTracks().forEach(t=>t.stop());micStream=null;}}
  async function recordAudio(){if(recorder?.state==='recording'){stopMic();toast('Đã dừng ghi âm.');return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Trình duyệt không hỗ trợ ghi âm từ micro.');return;}try{if(recordedURL){URL.revokeObjectURL(recordedURL);recordedURL=null;}micStream=await navigator.mediaDevices.getUserMedia({audio:true});let chunks=[];recorder=new MediaRecorder(micStream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{let blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});recordedURL=URL.createObjectURL(blob);let slot=$('#audio-recording');if(slot)slot.innerHTML=`<p class="muted small">Nghe lại phần vừa nói (chỉ lưu tạm):</p><audio controls src="${recordedURL}"></audio>`;if(micStream){micStream.getTracks().forEach(t=>t.stop());micStream=null;}};recorder.start();toast('Đang ghi âm. Bấm nút lần nữa để dừng.');}catch(err){toast('Không mở được micro: '+(err.message||'vui lòng kiểm tra quyền truy cập'));}}
  function recognizeSpeech(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Trình duyệt chưa hỗ trợ nhận diện giọng nói.');return;}try{recognition?.abort();recognition=new SR();recognition.lang='de-DE';recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onresult=e=>{const txt=e.results[0][0].transcript;ui.recognized=txt;state.practice.push({at:new Date().toISOString(),kind:'speech-transcript-match',matched:similarity(txt,ui.practiceTarget.de)});state.practice=state.practice.slice(-120);save();render();};recognition.onerror=e=>toast('Micro/nhận dạng không khả dụng: '+e.error+' (có thể cần mạng).');recognition.start();toast('Hãy nói tiếng Đức ngay bây giờ.');}catch(err){toast('Không thể bắt đầu nhận diện: '+err.message);}}
  function checkPractice(value){const mode=ui.practiceMode,letters=CONTENT.alphabet,correct=mode.startsWith('letter')?letters[ui.practiceItem].letter:ui.practiceTarget.de;
    let ok=norm(value)===norm(correct);ui.practiceDone=true;ui.practiceAnswer=value;state.practice.push({at:new Date().toISOString(),kind:mode,correct:ok});state.practice=state.practice.slice(-120);if(ok&&mode==='letter-write')state.lettersWritten[correct]=true;save();render();toast(ok?'Đúng rồi!':'Chưa chính xác. Hãy nghe lại câu mẫu.');}
  function addDays(n){let d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
  function reviewMark(kind){let keys=reviewKeys(),key=keys[ui.reviewIndex],item=state.cards[key];if(!item)return;const count=(item.success||0)+(kind==='easy'?1:0);let days=kind==='again'?1:kind==='hard'?2:[3,7,14,30,45,60][Math.min(count-1,5)];item.success=count;item.due=addDays(days);item.seen=(item.seen||0)+1;save();ui.reviewShow=false;ui.reviewIndex=(ui.reviewIndex+1)%keys.length;render();}
  function exportProgress(){let data=JSON.stringify({app:'Deutsch Starter V3',exportedAt:new Date().toISOString(),data:state},null,2),blob=new Blob([data],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Deutsch_Starter_Backup_'+localDay()+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Đã yêu cầu tải bản sao lưu. Kiểm tra thư mục Tải xuống/Tệp.');}
  async function importProgress(file){if(!file)return;if(file.size>4_000_000){toast('Tệp quá lớn (giới hạn 4 MB).');return;}try{let obj=JSON.parse(await file.text()),payload=obj.data||obj;let candidate;
      if(payload.version===3&&payload.completed&&payload.cards&&payload.settings){candidate=Object.assign(empty(),payload)}
      else if(payload.letters&&payload.completed){candidate=empty();candidate.letters=payload.letters||{};candidate.lettersWritten=payload.writes||{};candidate.legacyImported=true;}
      else throw new Error('Tệp không phải tiến độ Deutsch Starter hợp lệ.');
      if(!window.confirm('Nhập bản sao lưu sẽ THAY THẾ tiến độ hiện tại. Bạn đã xuất bản sao trước khi nhập chưa?'))return;
      state=candidate;save(false);ui.exam=null;ui.examResult=null;render();toast('Đã nhập tiến độ.');
    }catch(err){toast('Nhập tệp thất bại: '+err.message);}}
  function closeMenu(){$('#sidebar').classList.remove('open');$('#overlay').hidden=true;}
  function toggleMenu(){let open=$('#sidebar').classList.toggle('open');$('#overlay').hidden=!open;}
  document.addEventListener('click',async e=>{const nav=e.target.closest('[data-view]');if(nav){go(nav.dataset.view);return;}
    const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;
    try{
      if(a==='home')go('home');
      if(a==='open-alphabet')go('alphabet');
      if(a==='open-lessons')go('lessons');
      if(a==='open-practice')go('practice');
      if(a==='open-exams')go('exams');
      if(a==='open-progress')go('progress');
      if(a==='pick-level'||a==='select-level'){ui.level=el.dataset.level;go('lessons');}
      if(a==='select-letter'){ui.letter=Number(el.dataset.index);render();}
      if(a==='prev-letter'){ui.letter=Math.max(0,ui.letter-1);render();}
      if(a==='next-letter'){ui.letter=Math.min(29,ui.letter+1);render();}
      if(a==='say-letter')speak(CONTENT.alphabet[ui.letter].name,.7);
      if(a==='say-word')speak(CONTENT.alphabet[ui.letter].word,.78);
      if(a==='mark-letter'){state.letters[CONTENT.alphabet[ui.letter].letter]=true;save();render();toast('Đã ghi nhớ chữ cái.');}
      if(a==='check-letter'){let letter=CONTENT.alphabet[ui.letter].letter,value=($('#letter-write')?.value||'').trim();let good=norm(letter)===norm(value);if(good){state.lettersWritten[letter]=true;state.letters[letter]=true;save();}$('#letter-feedback').innerHTML=`<p class="answerline ${good?'':'bad'}">${good?'✓ Chính xác!':'✕ Chưa đúng. Đáp án là '+h(letter)}</p>`;}
      if(a==='select-sound'){ui.sound=Number(el.dataset.index);render();}
      if(a==='prev-sound'){ui.sound=Math.max(0,ui.sound-1);render();}
      if(a==='next-sound'){ui.sound=Math.min(CONTENT.phonics.length-1,ui.sound+1);render();}
      if(a==='say-sound')speak(CONTENT.phonics[ui.sound].example.replace(' / ','. '),.7);
      if(a==='open-lesson'){ui.lesson=el.dataset.id;ui.lessonQuiz=null;go('lesson');}
      if(a==='back-lessons')go('lessons');
      if(a==='complete-lesson'){state.completed[ui.lesson]=true;save();render();toast('Đã hoàn thành bài học.');}
      if(a==='say-lesson'){let l=allLessons().find(x=>x.id===ui.lesson);speak(l.phrases.map(p=>p[0]).join('. '),.75);}
      if(a==='say')speak(decodeURIComponent(el.dataset.text));
      if(a==='toggle-card'){let key=el.dataset.key;if(state.cards[key])delete state.cards[key];else state.cards[key]={due:localDay(),success:0,seen:0};save();render();}
      if(a==='lesson-quiz-answer'){let q=ui.lessonQuiz;if(q&&!q.answered){q.choice=Number(el.dataset.index);q.answered=true;state.practice.push({at:new Date().toISOString(),kind:'lesson-translation',correct:q.options[q.choice]===q.vi});state.practice=state.practice.slice(-120);save();render();}}
      if(a==='lesson-quiz-next'){let l=allLessons().find(x=>x.id===ui.lesson);ui.lessonQuiz=makeQuiz(l);render();}
      if(a==='practice-mode'){ui.practiceMode=el.dataset.mode;newPractice();render();}
      if(a==='practice-level'){ui.level=el.dataset.level;newPractice();render();}
      if(a==='practice-next'){newPractice();render();}
      if(a==='play-practice'||a==='play-practice-slow')speak(ui.practiceMode.startsWith('letter')?CONTENT.alphabet[ui.practiceItem].name:ui.practiceTarget.de,a==='play-practice-slow'?.65:state.settings.rate);
      if(a==='practice-choice'&&!ui.practiceDone)checkPractice(el.dataset.value);
      if(a==='check-practice'&&!ui.practiceDone)checkPractice($('#practice-text')?.value||'');
      if(a==='start-recognition')recognizeSpeech();
      if(a==='review-flip'){ui.reviewShow=!ui.reviewShow;render();}
      if(a==='review-prev'){let len=reviewKeys().length;ui.reviewIndex=(ui.reviewIndex+len-1)%len;ui.reviewShow=false;render();}
      if(a==='review-next'){let len=reviewKeys().length;ui.reviewIndex=(ui.reviewIndex+1)%len;ui.reviewShow=false;render();}
      if(a==='review-again')reviewMark('again');
      if(a==='review-hard')reviewMark('hard');
      if(a==='review-easy')reviewMark('easy');
      if(a==='dialog-say')speak(DIALOGUES[ui.dialogId].steps[ui.dialogStep][0]);
      if(a==='dialog-answer'){ui.dialogFeedback=Number(el.dataset.index);if(ui.dialogFeedback===DIALOGUES[ui.dialogId].steps[ui.dialogStep][2])speak(DIALOGUES[ui.dialogId].steps[ui.dialogStep][1][ui.dialogFeedback]);render();}
      if(a==='dialog-next'){let d=DIALOGUES[ui.dialogId];if(ui.dialogFeedback===d.steps[ui.dialogStep][2]){if(ui.dialogStep<d.steps.length-1){ui.dialogStep++;ui.dialogFeedback=null;render();}else{ui.dialogStep=0;ui.dialogFeedback=null;toast('Hoàn thành hội thoại!');render();}}}
      if(a==='dialog-reset'){ui.dialogStep=0;ui.dialogFeedback=null;render();}
      if(a==='exam-start'){ui.exam=makeExam();ui.examResult=null;render();}
      if(a==='exam-section'&&ui.exam){ui.exam.section=el.dataset.section;render();}
      if(a==='exam-say'&&ui.exam){speak(ui.exam.listening[Number(el.dataset.index)].text,.82);}
      if(a==='exam-sample-say'&&ui.exam){speak(ui.exam.speaking[Number(el.dataset.index)].sample,.78);}
      if(a==='exam-submit'&&ui.exam){if(window.confirm('Nộp bài và xem đáp án ngay bây giờ?'))finishExam(false);}
      if(a==='exam-cancel'&&ui.exam){if(window.confirm('Hủy bài thi đang làm? Các câu chưa nộp sẽ mất.')){stopMic();ui.exam=null;render();}}
      if(a==='exam-back'){ui.examResult=null;render();}
      if(a==='exam-record')await recordAudio();
      if(a==='say-test')speak('Guten Tag! Ich lerne Deutsch. Wie geht es Ihnen?',.8);
      if(a==='export')exportProgress();
      if(a==='choose-import')$('#import-file')?.click();
      if(a==='reset'){if(window.confirm('Bạn có chắc muốn xóa TOÀN BỘ tiến độ hiện tại? Hành động không thể hoàn tác nếu không có tệp sao lưu.')){localStorage.removeItem(KEY);state=empty();ui.exam=null;ui.examResult=null;save(false);render();toast('Đã đặt lại tiến độ.');}}
    }catch(err){console.error(err);toast('Thao tác không thành công: '+err.message);}
  });
  document.addEventListener('change',e=>{let el=e.target;
    if(el.dataset.actionChange==='exam-level'){ui.examLevel=el.value;render();}
    if(el.dataset.actionChange==='exam-board'){ui.examBoard=el.value;render();}
    if(el.dataset.actionChange==='exam-form'){ui.examForm=Number(el.value);render();}
    if(el.dataset.actionChange==='exam-skill'){ui.examSkill=el.value;render();}
    if(el.dataset.actionChange==='exam-mode'){ui.examMode=el.value;render();}
    if(el.dataset.actionChange==='dialog-select'){ui.dialogId=Number(el.value);ui.dialogStep=0;ui.dialogFeedback=null;render();}
    if(el.dataset.actionChange==='tts-rate'){state.settings.rate=Number(el.value);save(false);toast('Đã cập nhật tốc độ phát âm.');}
    if(el.dataset.examAnswer&&ui.exam)ui.exam.answers[el.dataset.examAnswer]=Number(el.value);
    if(el.id==='import-file')importProgress(el.files[0]);
  });
  document.addEventListener('input',e=>{let el=e.target;if(el.id==='practice-text')ui.practiceText=el.value;if(el.dataset.essay&&ui.exam){ui.exam.text[el.dataset.essay]=el.value;let hint=el.parentElement.nextElementSibling;if(hint?.classList.contains('hint'))hint.textContent=tokens(el.value).length+' từ · Chưa có chấm điểm ngữ pháp tự động';}});
  $('#menubtn').addEventListener('click',toggleMenu);$('#overlay').addEventListener('click',closeMenu);$('#quick-speak').addEventListener('click',()=>speak('Hallo! Willkommen bei Deutsch Starter.'));
  function updateConnection(){let isonline=navigator.onLine;$('#netbadge').textContent=isonline?'● Có kết nối':'● Ngoại tuyến';$('#netbadge').style.color=isonline?'#169575':'#b0702d';}
  window.addEventListener('online',updateConnection);window.addEventListener('offline',updateConnection);updateConnection();
  setInterval(()=>{let s=ui.exam;if(!s||s.finished||!s.deadline)return;if(s.deadline<=Date.now()){finishExam(true);toast('Đã hết giờ làm bài luyện.');}else if($('#exam-clock'))$('#exam-clock').textContent=examTime(s);},1000);
  if('serviceWorker'in navigator&&(window.isSecureContext||location.hostname==='localhost'))navigator.serviceWorker.register('./sw.js').catch(err=>console.warn('Service worker:',err));
  render();
})();
